// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address to, uint256 v, uint8 _decimals) public {
        vm.assume(caddress.code.length == 0); // EOA callee: low-level transferFrom succeeds
        vm.assume(to != address(0));
        vm.assume(_decimals < 77); // keep v * 10**decimals from overflowing
        vm.assume(v < type(uint256).max / (10 ** uint256(_decimals)));

        address[] memory tos = new address[](1);
        tos[0] = to;

        bool ok;
        try c.transfer(from, caddress, tos, v, _decimals) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }
        assertTrue(ok, "transfer must return true for successful external calls");
    }
}
